<script setup lang="ts">
/**
 * SplitButton.Submenu: a row that opens a list of its own, one level deep.
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/split-button.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { computed, inject, onMounted, useId, useTemplateRef, watch } from 'vue'

import * as zag from '@zag-js/menu'
import { normalizeProps, useMachine } from '@zag-js/vue'

import { Icon, followHighlight, returnFocus, useDirection } from '@polymorph/vue'
import { usePresence } from '@polymorph/vue/motion'
import styles from '@polymorph/recipes/controls/split-button.module.css'
import Kbd from '../structure/Kbd.vue'
import type { MenuEntry } from '../overlays/Menu.vue'

export interface SplitButtonSubmenuProps {
  entry: MenuEntry
}

defineOptions({ name: 'SplitButtonSubmenu', inheritAttrs: false })

const props = defineProps<SplitButtonSubmenuProps>()
const uid = useId()
const owner = inject<Record<string, any>>('polymorph:SplitButton', {})
const panel = useTemplateRef<HTMLElement>('panel')
const row = useTemplateRef<HTMLElement>('row')
const items = computed(() => (props.entry.kind === 'submenu' ? props.entry.items : []))
const documentDirection = useDirection(() => row.value)
const service = useMachine(
  zag.machine,
  computed(() => ({
    id: uid,
    dir: documentDirection.value,
    positioning: { placement: 'right-start', gutter: 2 },
    onSelect: (details) => {
      items.value.forEach(
        (item) => 'onSelect' in item && item.label === details.value && item.onSelect(),
      )
    },
  })),
)
const api = computed(() => zag.connect(service, normalizeProps))
const present = usePresence(() => api.value.open, panel)
const effect1 = () => {
  ;(owner.api?.setChild(service), api.value.setParent(owner.service))
}
onMounted(effect1)
const effect2 = () => {
  followHighlight(panel.value, api.value.highlightedValue)
}
onMounted(effect2)
watch(() => api.value.highlightedValue, effect2, { flush: 'post' })
const effect3 = () => {
  api.value.open || returnFocus(row.value, panel.value)
}
watch(() => api.value.open, effect3, { flush: 'post' })
</script>

<template>
  <template v-if="entry.kind === 'submenu'">
    <div
      v-if="entry.disabled"
      v-bind="owner.api?.getItemProps({ value: entry.label, disabled: true }) ?? {}"
      :class="styles.item"
      data-tone="neutral"
    >
      <span v-if="entry.icon !== undefined" :class="styles.rowGlyph">
        <Icon :name="entry.icon" size="sm" />
      </span>
      <span :class="styles.rowLabel">
        {{ entry.label }}
      </span>
      <span :class="styles.hint">
        <Icon name="next" size="sm" />
      </span>
    </div>
    <div
      v-else
      ref="row"
      v-bind="owner.api?.getTriggerItemProps(api) ?? {}"
      :class="styles.item"
      data-tone="neutral"
      tabindex="-1"
    >
      <span v-if="entry.icon !== undefined" :class="styles.rowGlyph">
        <Icon :name="entry.icon" size="sm" />
      </span>
      <span :class="styles.rowLabel">
        {{ entry.label }}
      </span>
      <span :class="styles.hint">
        <Icon name="next" size="sm" />
      </span>
    </div>
    <Teleport to="body">
      <div v-if="present" v-bind="api.getPositionerProps()">
        <div
          ref="panel"
          v-bind="api.getContentProps()"
          :class="styles.content"
          :style="{
            '--radix-dropdown-menu-content-available-height': 'var(--available-height)',
            '--radix-dropdown-menu-content-transform-origin': 'var(--transform-origin)',
          }"
          :hidden="undefined"
        >
          <template v-for="(entry, index) in items" :key="index">
            <div
              v-if="entry.kind === 'separator'"
              v-bind="api.getSeparatorProps()"
              :class="styles.separator"
            />
            <div v-else-if="entry.kind === 'label'" :class="styles.groupLabel">
              {{ entry.label }}
            </div>
            <div
              v-else-if="entry.kind === 'checkbox'"
              v-bind="
                api.getOptionItemProps({
                  type: 'checkbox',
                  value: entry.label,
                  checked: entry.checked,
                  disabled: entry.disabled,
                  closeOnSelect: false,
                  onCheckedChange: entry.onCheckedChange,
                })
              "
              :class="[styles.item, styles.checkbox]"
              tabindex="-1"
              @focus="api.setHighlightedValue(entry.label)"
            >
              <span :class="styles.check">
                <Icon v-if="entry.checked" name="confirm" size="sm" />
              </span>
              <span :class="styles.rowLabel">
                {{ entry.label }}
              </span>
            </div>
            <div
              v-else
              v-bind="api.getItemProps({ value: entry.label, disabled: entry.disabled })"
              :class="styles.item"
              :data-tone="entry.tone ?? 'neutral'"
              tabindex="-1"
              @focus="api.setHighlightedValue(entry.label)"
            >
              <span v-if="entry.icon !== undefined" :class="styles.rowGlyph">
                <Icon :name="entry.icon" size="sm" />
              </span>
              <span :class="styles.rowLabel">
                {{ entry.label }}
              </span>
              <span v-if="entry.kbd !== undefined" :class="styles.hint">
                <Kbd>
                  {{ entry.kbd }}
                </Kbd>
              </span>
            </div>
          </template>
        </div>
      </div>
    </Teleport>
  </template>
</template>
